css:
.dashboard-toast {
  position: absolute;
  right: clamp(28px, 7vw, 90px);
  bottom: 58px;
  width: min(330px, 34vw);
  padding: 18px 20px;
  border: 1px solid rgba(151, 211, 235, 0.22);
  border-radius: 4px;
  color: #97d3eb;
  background: rgba(8, 34, 42, 0.92);
  box-shadow: 0 22px 60px rgba(0, 0, 0, 0.34);
}
